<script setup lang="ts">
import {onMounted,onUnmounted,ref} from 'vue';import {setDisplayTimezone} from './domain';import {connect,request,errorText} from './api';import Icon from './components/Icon.vue';import TasksPage from './pages/TasksPage.vue';import CalendarPage from './pages/CalendarPage.vue';import ApplicationsPage from './pages/ApplicationsPage.vue';import InboxPage from './pages/InboxPage.vue';import SettingsPage from './pages/SettingsPage.vue';import Onboarding from './components/Onboarding.vue';import Notifications from './components/Notifications.vue';
const desktop=new URLSearchParams(location.search).get('desktop')==='1';
const exiting=ref(false),exitError=ref('');
async function exitApp(){
 if(exiting.value||!confirm('退出 OfferPilot 后将停止同步与提醒。已保存的数据会保留，确定退出？'))return;
 exiting.value=true;exitError.value='';
 try{await request('/app/exit','POST',{});}catch(e){exitError.value=errorText(e);exiting.value=false;}
}
const page=ref('tasks'),connected=ref(false),error=ref(''),loading=ref(true),onboarding=ref(false),notifications=ref(false),health=ref<any>(null);let timer:ReturnType<typeof setInterval>;
const names:Record<string,string>={tasks:'今日待办',calendar:'事件日历',applications:'申请看板',inbox:'收件识别',settings:'设置与诊断'};
async function refresh(){try{health.value=await request('/diagnostics');}catch{health.value=null;}}
async function start(){loading.value=true;error.value='';try{await connect();connected.value=true;const settings=await request('/settings');setDisplayTimezone(settings.timezone);onboarding.value=!settings.onboarding_completed;await refresh();}catch(e){error.value=errorText(e);}finally{loading.value=false;}}
onMounted(()=>{start();timer=setInterval(()=>{if(connected.value&&!document.hidden)refresh();},15000);});onUnmounted(()=>clearInterval(timer));
</script>
<template><div class="app-shell" :class="{desktop}"><aside class="sidebar"><a href="#" class="brand" @click.prevent="page='tasks'"><span class="brand-mark"><Icon name="leaf" :size="25"/></span><span>OfferPilot<small>让每一步，都有着落</small></span></a><div class="nav-label">我的求职空间</div><nav><button v-for="(label,key) in names" :key="key" :title="label" :aria-label="label" :class="{active:page===key}" @click="page=key"><Icon :name="String(key)==='calendar'?'calendar':String(key)==='inbox'?'inbox':String(key)==='settings'?'settings':'tasks'"/>{{label}}<span v-if="page===key" class="nav-dot"/></button></nav><div class="sidebar-note"><div class="little-orbit"><Icon name="leaf" :size="30"/></div><p>专注当下，<br>好机会值得认真准备。</p><span>本地保存 · 由你掌控</span></div><button class="sidebar-help" @click="onboarding=true"><span class="help-circle">?</span>使用引导<Icon name="chevron" :size="16"/></button><div class="local-status"><i :class="{offline:!health}"/>{{health?'本地服务运行中':'连接本地服务'}}<span>v1.0.0-rc.3</span></div></aside><main><header class="topbar"><span class="breadcrumb">我的空间 <span>/</span> <b>{{names[page]}}</b></span><div class="top-actions"><button v-if="desktop" class="text-button" :disabled="exiting" @click="exitApp">{{exiting?'正在退出…':'退出程序'}}</button><span class="private-label"><i/>本机保存 · 联网由你选择</span><button class="icon-button" aria-label="提醒中心" @click="notifications=true"><Icon name="bell"/></button><div class="avatar">我</div></div></header><div v-if="loading" class="connection-state"><span class="spinner"/>正在打开你的求职空间…</div><div v-else-if="!connected" class="connection-state"><Icon name="leaf" :size="42"/><h1>重新连接你的空间</h1><p>{{error}}</p><p class="muted">请从 OfferPilot 托盘或桌面快捷方式重新打开界面。</p><button class="button primary" @click="start">重新连接</button></div><template v-else><p v-if="exitError" class="error-box" role="alert">{{exitError}}</p><TasksPage v-if="page==='tasks'"/><CalendarPage v-else-if="page==='calendar'"/><ApplicationsPage v-else-if="page==='applications'"/><InboxPage v-else-if="page==='inbox'"/><SettingsPage v-else @onboarding="onboarding=true"/></template><footer class="app-footer"><span>每一份认真，都在靠近下一站。</span><span>{{desktop?'独立桌面窗口 · 关闭后在托盘继续运行':'OFFERPILOT LITE'}}</span></footer></main><Onboarding v-if="onboarding&&connected" @close="onboarding=false"/><Notifications v-if="notifications&&connected" @close="notifications=false"/></div></template>
